<template><main class="page feature-page market-page"><header class="topbar"><div><p class="eyebrow">虚拟市集</p><h1>羽毛兑换</h1></div><button @click="router.back()">← 地图</button></header><p class="notice">当前羽毛：{{ store.feathers }}</p><section class="feature-grid"><article v-for="item in shopItems" :key="item.id" class="feature-card"><h2>{{ item.name }}</h2><p class="muted">{{ item.description }}</p><p>{{ item.price }} 羽毛</p><button :disabled="store.feathers<item.price || store.items.includes(item.id)" @click="buy(item)">{{ store.items.includes(item.id) ? '已拥有' : '兑换' }}</button></article></section></main></template>
<script setup lang="ts">import { useRouter } from 'vue-router';import { useGameStore } from '../stores/gameStore';import { autoSave } from '../engine/SaveManager';import { itemCatalog } from '../data/resourceData';const router=useRouter();const store=useGameStore();const shopItems=itemCatalog.filter(item=>item.price>0);async function buy(item:{id:string;price:number}){if(store.feathers<item.price||store.items.includes(item.id))return;store.addFeathers(-item.price);store.addItem(item.id);await autoSave()}</script>